<script lang="ts">
	import { API, Constants, ExternalLink, Mutex, Permission, Utils } from "$lib";
	import type { CreateMangaRequest } from "$lib/API/Manga";
	import { HTTPError } from "$lib/HTTP";
	import Session from "$lib/stores/Session";
	import equal from "fast-deep-equal";
	import { createMutationOwner, authenticatedMutation, type MutationIntent } from "$platform/authenticated-mutation";
	import { createEditorCoverReader, savedCoverDraft, mergeCurrentCoverDrafts } from "$platform/editor-cover-read";
	import { requireMutationAcknowledgement, reportCurrentMutationFailure } from "$platform/mutation-feedback";
	import CoversSection from "$lib/components/draft/manga/CoversSection.svelte";
	import LinksSection from "$lib/components/draft/manga/LinksSection.svelte";
	import MetadataSection from "$lib/components/draft/manga/MetadataSection.svelte";
	import RelationsSection from "$lib/components/draft/manga/RelationsSection.svelte";
	import TitleSection from "$lib/components/draft/manga/TitleSection.svelte";
	import { Button, buttonVariants } from "$lib/components/ui/button";
	import * as Empty from "$lib/components/ui/empty";
	import { Separator } from "$lib/components/ui/separator";
	import { Spinner } from "$lib/components/ui/spinner";
	import * as Tabs from "$lib/components/ui/tabs/index.js";
	import { populateTagList } from "$lib/stores";
	import { cn } from "$lib/Utils";
	import { Check, XIcon } from "@lucide/svelte";
	import { StatusCodes } from "http-status-codes";
	import { onDestroy, onMount } from "svelte";
	import { toast } from "svelte-sonner";
	import Guidelines from "./Guidelines.svelte";
	import TagsSection from "./TagsSection.svelte";

	const { pathname } = window.location;
	const mutex = new Mutex();
	const STATE = {
		Idle: 0,
		CreatingEntry: 1,
		UploadingCovers: 2,
		CreatingRelations: 3,
		Done: 4,
		Error: 5
	} as const;
	let mutexState = $state<(typeof STATE)[keyof typeof STATE]>(STATE.Idle);

	let manga = $state<Manga>();
	const creationOwner = createMutationOwner(() => pathname + "|" + window.location.pathname);
	const createdCoverReader = createEditorCoverReader(() => manga?.id ?? "");
	let creationActor = $state<string>(), creationPayload = $state.raw<CreateMangaRequest>();
	let creationUnknown = $state(false), unknownCoverIds = $state<string[]>([]), unknownRelationKeys = $state<string[]>([]);
	let acceptedRelationKeys = $state<string[]>([]), acknowledgedCovers = $state<CoverDraft[]>([]), recoveryReadRequired = $state(false);
	const canRetryCreatedDraft = $derived(!!manga && (manga as Manga & { can_mutate?: boolean }).can_mutate !== false && creationActor === $Session?.identity?.id && !creationUnknown && !unknownCoverIds.length && !unknownRelationKeys.length && !recoveryReadRequired);
	let draft = $state<MangaDraft>({
		title: "",
		language: "ja",
		status: Constants.Manga.PublicationStatus.Ongoing,
		content_rating: Constants.Manga.ContentRating.Safe,

		covers: [],
		alt_titles: [],
		tags: [],
		authors: [],
		artists: [],
		links: [],
		relations: []
	});

	const isCompletedOrCancelled = $derived(
		[Constants.Manga.PublicationStatus.Completed, Constants.Manga.PublicationStatus.Cancelled].includes(draft.status)
	);
	const isVolumeValid = $derived(
		isCompletedOrCancelled && draft.last_volume ? Utils.isValidVolumeChapter(draft.last_volume) : true
	);
	const isChapterValid = $derived(
		isCompletedOrCancelled && draft.last_chapter ? Utils.isValidVolumeChapter(draft.last_chapter) : true
	);
	const isValid = $derived(
		draft?.title &&
			isVolumeValid &&
			isChapterValid &&
			draft.authors.length &&
			draft.artists.length &&
			draft.covers.every(e => e.valid) &&
			draft.alt_titles.every(e => e.valid) &&
			draft.links.every(e => e.valid)
	);

	onMount(async () => {
		try {
			await populateTagList();
		} catch (e) {
			console.error(e);
		}
	});

	onDestroy(() => {
		draft.covers.forEach(cover => {
			if (cover.thumbnail && cover.thumbnail.startsWith("blob:")) {
				URL.revokeObjectURL(cover.thumbnail);
			}
		});
	});

	const onSubmit = (ev?: SubmitEvent) => {
		ev?.preventDefault(); ev?.stopPropagation(); ev?.stopImmediatePropagation();
		if (mutex.isLocked() || mutexState === STATE.Done || !draft || !isValid) return;
		let intent: MutationIntent;
		try {
			intent = creationOwner.capture();
			if (creationUnknown || (manga && (!canRetryCreatedDraft || intent.actor !== creationActor))) {
				intent.release(); throw new HTTPError(409, "A previous draft step has an unknown outcome or belongs to another account. Inspect the actual saved draft before a new deliberate request; no create/upload was replayed.", "Draft recovery requires review");
			}
		} catch (cause) { reportCurrentMutationFailure("Draft request not admitted", cause, () => true); return; }
		return mutex.exec(async () => {
			try {
				intent.assert(); await createManga(intent); intent.assert();
				await uploadCovers(intent); intent.assert();
				await createRelations(intent); intent.assert();
				recoveryReadRequired = true;
				manga = await createdCoverReader.manga(manga!, intent); intent.assert();
				recoveryReadRequired = false; mutexState = STATE.Done;
			} catch (cause) {
				if (!intent.alive()) return;
				mutexState = manga || creationUnknown ? STATE.Error : STATE.Idle;
				reportCurrentMutationFailure("Draft steps not completed", cause, intent.alive);
			}
		}).finally(() => intent.release());
	};

	const createManga = async (intent: MutationIntent) => {
		if (!draft) {
			return;
		}

		const payload: CreateMangaRequest = {
			title: draft.title,
			description: draft.description || undefined,
			year: draft.year || undefined,
			language: draft.language,
			demographic: draft.demographic || undefined,
			status: draft.status,
			content_rating: draft.content_rating,

			last_volume: draft.last_volume || undefined,
			last_chapter: draft.last_chapter || undefined,

			alt_titles: draft.alt_titles.reduce(
				(acc, { language, title }) => {
					acc[language] ??= [];
					acc[language].push(title);
					return acc;
				},
				{} as Record<string, string[]>
			),

			tags: draft.tags,
			authors: draft.authors.map(e => e.id),
			artists: draft.artists.map(e => e.id),

			links: draft.links.reduce(
				(acc, { code, link }) => {
					link = ExternalLink.validate(code, link);
					if (link) acc[code] = link;
					return acc;
				},
				{} as Record<string, string>
			)
		};

		intent.assert();
		const submitted = structuredClone($state.snapshot(payload));
		if (manga) {
			if (!equal(submitted, creationPayload)) throw new HTTPError(409, "The acknowledged title metadata differs from this draft. Use Edit saved draft to submit an explicit versioned change. Title creation was not repeated.", "Saved draft metadata changed");
			return;
		}
		if (creationUnknown) throw new HTTPError(409, "The previous title creation may have succeeded. Inspect My drafts; a second title was not created.");
		mutexState = STATE.CreatingEntry;
		let knownRejection = false;
		try {
			const result = await authenticatedMutation<Manga>("/manga", "POST", submitted, intent);
			knownRejection = !!result && result.status >= 400 && result.status < 500;
			requireMutationAcknowledgement(result, 201, true); intent.assert();
			if (!result!.body!.id || !Number.isInteger(result!.body!.version) || result!.body!.version <= 0 || !result!.body!.relationships) throw new HTTPError(502, "No real created title identity/version was confirmed. Inspect My drafts before any new create request.", "Title creation outcome unknown");
			// Actual acknowledgement is retained before any subsequent cover request.
			manga = result!.body!; creationActor = intent.actor; creationPayload = submitted;
		} catch (cause) { if (!knownRejection && intent.alive()) creationUnknown = true; throw cause; }
	};

	const uploadCovers = async (intent: MutationIntent) => {
		intent.assert(); if (!manga) throw new HTTPError(409, "No acknowledged saved title is available.");
		mutexState = STATE.UploadingCovers;
		try {
			for (const row of draft.covers) {
				intent.assert(); if (!row.file) continue; // already acknowledged: never POST again
				if (unknownCoverIds.includes(row.id!)) throw new HTTPError(409, "This cover upload has an unknown outcome. Inspect the saved draft rather than replaying its File.");
				const form = new FormData(); form.append("file", row.file); form.append("language", row.language!);
				if (row.volume) form.append("volume", row.volume);
				if (row.description) form.append("description", row.description);
				if (row.main) form.append("main", "true");
				let knownRejection = false;
				try {
					const result = await authenticatedMutation<Cover>(`/cover/${encodeURIComponent(manga.id)}`, "POST", form, intent);
					knownRejection = !!result && result.status >= 400 && result.status < 500;
					requireMutationAcknowledgement(result, 200, true); intent.assert();
					const body = result!.body!;
					if (!body.id || !Number.isInteger(body.version) || body.version <= 0) throw new HTTPError(502, "No real cover ID/version was acknowledged.", "Cover outcome unknown");
					const oldThumbnail = row.thumbnail, saved = savedCoverDraft(manga, body, !!row.main);
					if (saved.main) acknowledgedCovers = acknowledgedCovers.map(other => ({ ...other, main: false }));
					acknowledgedCovers = [...acknowledgedCovers.filter(other => other.id !== saved.id), saved];
					Object.assign(row, saved, { file: undefined, deleted: undefined });
					if (oldThumbnail?.startsWith("blob:")) URL.revokeObjectURL(oldThumbnail);
				} catch (cause) { if (!knownRejection && intent.alive()) unknownCoverIds = [...unknownCoverIds, row.id!]; throw cause; }
			}
		} catch (cause) {
			if (!intent.alive()) throw cause;
			recoveryReadRequired = true;
			try {
				const previous = $state.snapshot(acknowledgedCovers), edited = $state.snapshot(draft.covers);
				const currentManga = await createdCoverReader.manga(manga, intent);
				const currentCovers = await createdCoverReader.covers(currentManga, intent); intent.assert();
				const saved = currentCovers.map(cover => savedCoverDraft(currentManga, cover));
				acknowledgedCovers = saved; draft.covers = mergeCurrentCoverDrafts(previous, edited, saved); manga = currentManga; recoveryReadRequired = false;
			} catch { if (intent.alive()) throw new HTTPError(0, "The existing title and acknowledged cover IDs were retained, but fresh owner cover data could not be confirmed. Open Edit saved draft to reconcile; no title or cover was replayed.", "Saved draft reconciliation unavailable"); }
			if (unknownCoverIds.length) throw new HTTPError(0, "A cover may have been accepted without its acknowledgement. The actual saved covers were read; pending Files were not matched by filename or replayed. Open Edit saved draft and review its current covers before another deliberate upload.", "Cover outcome unknown");
			throw cause;
		}
	};

	const createRelations = async (intent: MutationIntent) => {
		intent.assert(); if (!manga) throw new HTTPError(409, "No acknowledged saved title is available.");
		mutexState = STATE.CreatingRelations;
		for (const row of draft.relations) {
			intent.assert(); if (row.id === manga.id || row.deleted) continue;
			const key = JSON.stringify([row.id, row.type]);
			if (acceptedRelationKeys.includes(key)) continue;
			if (unknownRelationKeys.includes(key)) throw new HTTPError(409, "This relation has an unknown outcome. Inspect the current saved draft before another deliberate change.");
			let knownRejection = false;
			try {
				const result = await authenticatedMutation<Relation & { manga_version: number }>(`/manga/${encodeURIComponent(manga.id)}/relations`, "POST", { related_id: row.id, type: row.type, version: manga.version }, intent);
				knownRejection = !!result && result.status >= 400 && result.status < 500;
				requireMutationAcknowledgement(result, 201, true); intent.assert();
				if (result!.body!.id !== row.id || result!.body!.type !== row.type) throw new HTTPError(502, "No matching relation acknowledgement was returned.");
				acceptedRelationKeys = [...acceptedRelationKeys, key]; Object.assign(row, result!.body!, { new: false });
				if (!Number.isSafeInteger(result!.body!.manga_version) || result!.body!.manga_version <= 0) throw new HTTPError(502, "The actual owning title version was not returned. Reconcile saved state before continuing.");
				manga.version = result!.body!.manga_version;
			} catch (cause) {
				if (!intent.alive()) throw cause;
				if (!knownRejection) unknownRelationKeys = [...unknownRelationKeys, key];
				recoveryReadRequired = true;
				try {
					const current = await createdCoverReader.manga(manga, intent); intent.assert();
					if (current.relationships.relations?.some(relation => relation.id === row.id && relation.type === row.type)) {
						acceptedRelationKeys = [...new Set([...acceptedRelationKeys, key])]; unknownRelationKeys = unknownRelationKeys.filter(other => other !== key);
					}
					manga = current; recoveryReadRequired = false;
				} catch { /* retain exact acknowledged state; recovery stays fenced */ }
				throw cause;
			}
		}
	};
</script>

{#if mutexState === STATE.Idle}
	<form class="flex flex-auto flex-col space-y-5" onsubmit={onSubmit}>
		<Tabs.Root class="flex-auto space-y-5" value="title">
			<Tabs.List>
				<Tabs.Trigger value="title">Title</Tabs.Trigger>
				<Tabs.Trigger value="metadata">Metadata</Tabs.Trigger>
				<Tabs.Trigger value="tags">Tags</Tabs.Trigger>
				<Tabs.Trigger value="links">Links</Tabs.Trigger>
				<Tabs.Trigger value="relations">Relations</Tabs.Trigger>
				<Tabs.Trigger value="covers">Covers</Tabs.Trigger>
			</Tabs.List>
			<Tabs.Content class="space-y-5" value="title">
				<TitleSection bind:draft disabled={$mutex} />
			</Tabs.Content>
			<Tabs.Content class="space-y-5" value="metadata">
				<MetadataSection bind:draft {isCompletedOrCancelled} {isVolumeValid} {isChapterValid} disabled={$mutex} />
			</Tabs.Content>
			<Tabs.Content class="space-y-5" value="tags">
				<TagsSection bind:draft enabled disabled={$mutex} />
			</Tabs.Content>
			<Tabs.Content class="space-y-5" value="links">
				<LinksSection bind:draft enabled disabled={$mutex} />
			</Tabs.Content>
			<Tabs.Content class="space-y-5" value="relations">
				<RelationsSection bind:draft enabled={Permission.Manga.canEditRelations()} disabled={$mutex} />
			</Tabs.Content>
			<Tabs.Content class="space-y-5" value="covers">
				<CoversSection bind:draft enabled disabled={$mutex} />
			</Tabs.Content>
		</Tabs.Root>
		<Separator />
		<div class="bg-background sticky bottom-0 flex items-center justify-end gap-1 py-1">
			<Button type="submit" disabled={$mutex || !isValid}>Save</Button>
		</div>
	</form>
	<div class="space-y-2">
		<strong class="block text-xl font-semibold">Guidelines</strong>
		<Guidelines />
	</div>
{:else}
	<Empty.Root>
		<Empty.Header>
			<Empty.Media>
				<Check class={cn("size-10 scale-0 transition", mutexState === STATE.Done && "scale-100")} />
				<XIcon class={cn("absolute size-10 scale-0 transition", mutexState === STATE.Error && "scale-100")} />
				<Spinner
					class={cn(
						"absolute size-10 scale-0 transition",
						![STATE.Done, STATE.Error].includes(<any>mutexState) && "scale-100 "
					)}
				/>
			</Empty.Media>
			<Empty.Title>
				{#if mutexState === STATE.CreatingEntry}
					Creating Draft
				{:else if mutexState === STATE.UploadingCovers}
					Uploading Covers
				{:else if mutexState === STATE.CreatingRelations}
					Creating Relations
				{:else if mutexState === STATE.Done}
					Draft successfully created
				{:else if mutexState === STATE.Error}
					Error
				{/if}
			</Empty.Title>
		</Empty.Header>
		{#if manga && mutexState === STATE.Done}
			<Empty.Content>
				<div class="flex flex-wrap items-center justify-center gap-2">
					<a
						class={buttonVariants({ class: "border-none", variant: "outline" })}
						href="/title/{manga.id}/edit{new URLSearchParams({
							...(manga.state === Constants.State.Published ? {} : { draft: 'true' })
						})}"
					>
						Edit draft
					</a>
					<a
						class={buttonVariants({ class: "border-none", variant: "outline" })}
						href="/title/{manga.id}{new URLSearchParams({
							...(manga.state === Constants.State.Published ? {} : { draft: 'true' })
						})}"
					>
						Preview draft
					</a>
					<a class={buttonVariants({ class: "border-none", variant: "outline" })} href="/drafts/title">
						View my drafts
					</a>
				</div>
			</Empty.Content>
		{:else if mutexState === STATE.Error}
			<Empty.Content>
				<div class="flex flex-wrap items-center justify-center gap-2">
					{#if manga}
						<Button variant="outline" disabled={$mutex || !isValid || !canRetryCreatedDraft} onclick={() => onSubmit()}>Retry remaining draft steps</Button>
						<a class={buttonVariants({ class: "border-none", variant: "outline" })} href={`/title/${encodeURIComponent(manga.id)}/edit?draft=true`}>Edit saved draft</a>
					{/if}
					<a class={buttonVariants({ class: "border-none", variant: "outline" })} href="/drafts/title">
						View my drafts
					</a>
				</div>
			</Empty.Content>
		{/if}
	</Empty.Root>
{/if}
